ALTER TABLE users ADD COLUMN password_hash TEXT;
ALTER TABLE users ADD COLUMN must_change_password INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN avatar TEXT;
ALTER TABLE users ADD COLUMN bio TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN phone TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN password_version INTEGER NOT NULL DEFAULT 0;
ALTER TABLE messages ADD COLUMN author_snapshot TEXT NOT NULL DEFAULT '{}';
ALTER TABLE tickets ADD COLUMN team TEXT NOT NULL DEFAULT 'technical';
CREATE TABLE sessions (hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL,password_version INTEGER NOT NULL);
CREATE TABLE auth_attempts (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE direct_threads (id TEXT PRIMARY KEY,member_a TEXT NOT NULL REFERENCES users(id),member_b TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(member_a,member_b));
CREATE TABLE meetings (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,host_id TEXT NOT NULL REFERENCES users(id),year_id TEXT REFERENCES years(id),group_id TEXT REFERENCES groups(id),module_id TEXT REFERENCES modules(id),start_at TEXT NOT NULL,duration INTEGER NOT NULL,status TEXT NOT NULL,capacity INTEGER NOT NULL,mode TEXT NOT NULL,room_name TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE meeting_attendance (meeting_id TEXT NOT NULL REFERENCES meetings(id),user_id TEXT NOT NULL REFERENCES users(id),joined_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,left_at TEXT,PRIMARY KEY(meeting_id,user_id));
CREATE TABLE meeting_requests (meeting_id TEXT NOT NULL REFERENCES meetings(id),user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(meeting_id,user_id));
CREATE TABLE meeting_bans (meeting_id TEXT NOT NULL REFERENCES meetings(id),user_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(meeting_id,user_id));
CREATE INDEX idx_messages_room ON messages(room,created_at);
CREATE INDEX idx_tickets_owner ON tickets(owner_id,created_at);
CREATE INDEX idx_users_group ON users(group_id,status);
CREATE INDEX idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX idx_meetings_scope ON meetings(year_id,group_id,start_at);
